def chart(kind='candles',color='#64CFD7',ivory=False):
    g=[]
    for x in range(0,1201,120):g.append(f'<line class="gridline" x1="{x}" y1="0" x2="{x}" y2="500"/>')
    for y in range(0,501,100):g.append(f'<line class="gridline" x1="0" y1="{y}" x2="1200" y2="{y}"/>')
    vals=[310-2.8*i+52*math.sin(i*.38)+18*math.cos(i*.91) for i in range(56)]
    if kind=='candles':
        for i,y in enumerate(vals):
            x=25+i*21; op=y+math.sin(i*1.22)*22; cl=y+math.cos(i*.71)*23; c='#65D7C4' if cl<op else '#E19B8C'
            g.append(f'<g class="candle"><line x1="{x}" y1="{min(op,cl)-24:.1f}" x2="{x}" y2="{max(op,cl)+21:.1f}" stroke="{c}" stroke-width="2"/><rect x="{x-5}" y="{min(op,cl):.1f}" width="10" height="{max(4,abs(cl-op)):.1f}" fill="{c}"/><rect x="{x-5}" y="{450-(i%7)*6}" width="10" height="{20+(i%7)*6}" fill="{c}" opacity=".22"/></g>')
    else:
        d='M '+' L '.join(f'{25+i*21},{y:.1f}' for i,y in enumerate(vals))
        g.append(f'<path class="price-path" d="{d}" fill="none" stroke="{color}" stroke-width="5"/>')
        g.append(f'<path d="{d} L1180,500 L25,500Z" fill="{color}" fill-opacity=".06"/>')
    if kind=='compare':
        d2='M '+' L '.join(f'{25+i*21},{y+62*math.sin(i*.16)+40:.1f}' for i,y in enumerate(vals))
        g.append(f'<path class="price-path" d="{d2}" fill="none" stroke="#E9A28F" stroke-width="4"/>')
    return '<svg viewBox="0 0 1200 500" aria-hidden="true">'+''.join(g)+'</svg>'

def panel(id,title='ILLUSTRATIVE CHART',kind='candles',extra=''):
    note='' if id.startswith('sx2-perspective') else '<div class="chart-note illustrative">ILLUSTRATIVE · NOT LIVE DATA</div>'
    return f'<div id="{id}" class="panel" {extra}><div class="panel-head"><span>{title}</span><span>VIEW / 01</span></div>{chart(kind)}{note}</div>'

def scene(id,dur,css,html,js):
    if SELECT and id not in SELECT:return
    content=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{id}</title></head><body><template id="{id}-template"><style>{FONT}\n{BASE}\n#{id}-root{{position:absolute;inset:0;width:100%;height:100%;background:#071424}}\n{css}</style><div id="{id}-root" data-composition-id="{id}" data-width="1920" data-height="1080" data-duration="{dur}"><div class="stage">{html}</div></div><script>(()=>{{const tl=gsap.timeline({{paused:true}});const E=(s,a,b,t)=>tl.fromTo(s,a,{{...b,immediateRender:true}},t);{js}\nwindow.__timelines=window.__timelines||{{}};window.__timelines["{id}"]=tl;}})();</script></template></body></html>'''
    (P/'compositions'/f'{id}.html').write_text(content)

