# 05 — three fast graphic phases share a continuous diagonal trajectory.
s='sx2-montage'
scene(s,4,f'''#{s}-root{{background:#165DFF}}#{s}-phase-a .mono{{color:#FFFFFF}}#{s}-phase-a,#{s}-phase-b,#{s}-phase-c{{position:absolute;inset:0}}#{s}-phase-b{{background:#F2EEE5;color:#071424;opacity:0}}#{s}-phase-c{{background:#071424;opacity:0}}.montage-number{{position:absolute;left:70px;top:140px;font-size:650px;line-height:1;color:#FFFFFF11}}.montage-type{{position:absolute;left:100px;top:400px;font-size:220px;z-index:4}}.montage-sub{{position:absolute;left:110px;bottom:125px;font-size:25px}}#{s}-card-a{{left:1120px;top:110px;width:900px;height:880px}}#{s}-card-b{{left:990px;top:190px;width:1040px;height:620px;background:#071424}}#{s}-card-c{{left:1120px;top:230px;width:890px;height:620px}}#{s}-slash{{position:absolute;left:1680px;top:-100px;width:28px;height:1400px;background:#B3D0FF;transform-origin:center}}''',f'''<div id="{s}-phase-a"><div class="montage-number display" aria-hidden="true">01</div><div class="montage-type serif">Chart.</div><div class="montage-sub mono">TURN SIGNAL INTO PERSPECTIVE.</div>{panel(s+'-card-a','ILLUSTRATIVE / CHART')}</div><div id="{s}-phase-b"><div class="montage-number display" style="color:#07142420" aria-hidden="true">02</div><div class="montage-type serif">Explore.</div><div class="montage-sub mono">WIDEN YOUR POINT OF VIEW.</div>{panel(s+'-card-b','ILLUSTRATIVE / EXPLORE','compare')}</div><div id="{s}-phase-c"><div class="montage-number display" aria-hidden="true">03</div><div class="montage-type serif">Connect.</div><div class="montage-sub mono">FOLLOW THE THREAD.</div>{network(s+'-card-c')}</div><div id="{s}-slash"></div>''',f'''E("#{s}-phase-a .montage-type",{{x:-220,skewX:-8}},{{x:0,skewX:0,duration:.38,ease:"expo.out"}},0);E("#{s}-card-a",{{x:350,rotation:12,rotationY:-20}},{{x:0,rotation:-5,rotationY:-12,duration:.6,ease:"power4.out"}},0);E("#{s}-slash",{{rotation:23,x:-2050}},{{rotation:23,x:0,duration:1.0,ease:"power2.inOut"}},.6);tl.set("#{s}-phase-a",{{opacity:0}},1.3333333333);tl.set("#{s}-phase-b",{{opacity:1}},1.3333333333);E("#{s}-phase-b .montage-type",{{y:150}},{{y:0,duration:.35,ease:"expo.out"}},1.3333333333);E("#{s}-card-b",{{x:350,rotationY:18,rotation:7}},{{x:0,rotationY:-8,rotation:-3,duration:.65,ease:"power4.out"}},1.3333333333);tl.set("#{s}-phase-b",{{opacity:0}},2.6666666667);tl.set("#{s}-phase-c",{{opacity:1}},2.6666666667);E("#{s}-phase-c .montage-type",{{scale:.8}},{{scale:1,duration:.38,ease:"power4.out"}},2.6666666667);E("#{s}-card-c",{{x:360,rotationY:18,rotation:8}},{{x:0,rotationY:-10,rotation:3,duration:.65,ease:"power4.out"}},2.6666666667);E("#{s}-card-c .network-path",{{strokeDashoffset:1200}},{{strokeDashoffset:0,duration:.8,stagger:.06,ease:"power2.inOut"}},2.72);E("#{s}-card-c .network-dot",{{opacity:0}},{{opacity:1,duration:.28,stagger:.16,ease:"power2.out"}},2.75);E("#{s}-card-b .price-path",{{strokeDasharray:1800,strokeDashoffset:1800}},{{strokeDashoffset:0,duration:.8,stagger:.12,ease:"power2.inOut"}},1.36);tl.to("#{s}-slash",{{x:500,duration:.5,ease:"power3.inOut"}},3.5);''')
