# 07 — quiet identity and a fully legible, credited five-second close.
s='sx2-close'
scene(s,5,f'''#{s}-root{{background:#071424}}#{s}-studio{{position:absolute;left:104px;top:92px;font-size:26px;color:#B9CFFE}}#{s}-title{{position:absolute;left:100px;top:255px;width:1730px;font-size:178px}}#{s}-title .serif{{font-size:208px;color:#B9CFFE}}#{s}-bar{{position:absolute;left:110px;top:784px;width:130px;height:12px;background:#165DFF;transform-origin:left}}#{s}-product{{position:absolute;right:104px;top:862px;font-size:36px}}#{s}-note{{position:absolute;left:104px;top:864px;font-size:20px;color:#B6C3D5}}#{s}-credit{{color:#B6C3D5}}''',f'''<div id="{s}-studio" class="mono">CREATED BY <span style="color:#F2EEE5">STUDIOX VIEWPORT</span></div><div id="{s}-title"><div class="mask"><div class="display word">Great ideas should</div></div><div class="mask"><div class="serif word">move faster.</div></div></div><div id="{s}-bar"></div><div id="{s}-product" class="display">TradingView</div><div id="{s}-note" class="mono">Independent concept film · Illustrative charts</div><div id="{s}-credit" class="credit">Catalyst — Scott Buckley · CC BY 4.0 · scottbuckley.com.au</div>''',f'''E("#{s}-title .word",{{y:230}},{{y:0,duration:.85,stagger:.12,ease:"power4.out"}},.1);E("#{s}-studio",{{opacity:0,y:10}},{{opacity:1,y:0,duration:.5,ease:"power2.out"}},0);E("#{s}-bar",{{scaleX:0}},{{scaleX:1,duration:.7,ease:"power3.inOut"}},.5);''')
# Thin orchestrator: no animation of timed hosts.
if SELECT:sys.exit(0)
slots=''.join(f'<div id="{id}-slot" class="clip" data-composition-id="{id}" data-composition-src="compositions/{id}.html" data-start="{start}" data-duration="{dur}" data-track-index="1" data-width="1920" data-height="1080"></div>' for id,start,dur,copy in SCENES)
(P/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=1920, height=1080"><title>TradingView — Created by StudioX Viewport</title><style>{FONT}*{{box-sizing:border-box}}html,body{{margin:0;width:100%;height:100%;overflow:hidden;background:#071424}}#root{{position:relative;width:100%;height:100%;overflow:hidden;perspective:1800px}}#root>.clip{{position:absolute;inset:0;overflow:hidden}}</style><script src="assets/gsap.min.js"></script></head><body><div id="root" data-composition-id="studiox-v2" data-start="0" data-duration="30" data-width="1920" data-height="1080" data-fps="30">{slots}<audio id="sx2-soundtrack" class="clip" src="assets/soundtrack.wav" data-start="0" data-duration="30" data-track-index="10" data-volume="1" preload="auto"></audio></div><script>window.__timelines=window.__timelines||{{}};window.__timelines["studiox-v2"]=gsap.timeline({{paused:true}});</script></body></html>''')
(P/'storyboard.json').write_text(json.dumps({'id':'studiox-v2','width':1920,'height':1080,'fps':30,'duration':30,'palette':{'ink':'#071424','blue':'#165DFF','ivory':'#F2EEE5'},'scenes':[{'id':id,'start':start,'duration':dur,'copy':copy,'file':f'compositions/{id}.html'} for id,start,dur,copy in SCENES],'source':'TradingView public homepage chart asset; additional vectors are illustrative','credit':'Catalyst — Scott Buckley · CC BY 4.0 · scottbuckley.com.au'},indent=2))
